import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws IOException {
        StreamTokenizer in = new StreamTokenizer(new BufferedReader(new InputStreamReader(System.in)));
        in.nextToken();
        int n = (int) in.nval;
        int[] v = new int[n];
        for (int i = 0; i < n; i++) {
            in.nextToken();
            v[i] = (int) in.nval;
        }

        // Comprime a sequencia em blocos (runs) de valores consecutivos iguais.
        // Em qualquer marcacao valida, cada run contribui com no maximo um numero marcado.
        int[] runVal = new int[n];
        int R = 0;
        for (int i = 0; i < n; i++) {
            if (i == 0 || v[i] != v[i - 1]) runVal[R++] = v[i];
        }

        // Para cada valor, guarda os indices dos runs (em ordem crescente)
        @SuppressWarnings("unchecked")
        ArrayList<Integer>[] runsByVal = new ArrayList[n + 1];
        for (int i = 0; i <= n; i++) runsByVal[i] = new ArrayList<>();
        boolean[] seen = new boolean[n + 1];
        ArrayList<Integer> distinct = new ArrayList<>();
        for (int t = 0; t < R; t++) {
            int c = runVal[t];
            runsByVal[c].add(t);
            if (!seen[c]) { seen[c] = true; distinct.add(c); }
        }

        // Resposta pelo menos 1 (um unico numero marcado e sempre valido).
        int ans = 1;

        // Para cada par de valores distintos (a, b): o melhor conjunto marcado
        // alterna a e b. Isso equivale a escolher uma sub-sequencia da lista de
        // runs filtrada (so runs de valor a ou b) sem dois iguais adjacentes,
        // o que a gulosa resolve de forma otima em strings binarias.
        int K = distinct.size();
        for (int i = 0; i < K; i++) {
            int a = distinct.get(i);
            ArrayList<Integer> la = runsByVal[a];
            for (int j = i + 1; j < K; j++) {
                int b = distinct.get(j);
                ArrayList<Integer> lb = runsByVal[b];

                // Merge dos indices dos runs; gulosa: pega run se valor difere do ultimo pego
                int pa = 0, pb = 0, sa = la.size(), sb = lb.size();
                int last = 0, cnt = 0;
                while (pa < sa || pb < sb) {
                    int val;
                    if (pb >= sb || (pa < sa && la.get(pa) < lb.get(pb))) { val = a; pa++; }
                    else { val = b; pb++; }
                    if (val != last) { cnt++; last = val; }
                }
                if (cnt > ans) ans = cnt;
            }
        }

        System.out.println(ans);
    }
}
